const http = require('http');
const formidable = require('formidable');
const axios = require('/testbed/lib');

(async () => {
  const server = http.createServer((req, res) => {
    const form = new formidable.IncomingForm();
    form.parse(req, (err, fields, files) => {
      if (err) { res.end(JSON.stringify({error: String(err)})); return; }
      res.end(JSON.stringify({fields, files}));
    });
  }).listen(0, async () => {
    const url = 'http://localhost:' + server.address().port + '/';
    const FormData = global.FormData;
    const data = new FormData();
    data.append('somePropety', 'someValue');
    data.append('file1', new Blob(['blob-content'], {type: 'image/jpeg'}), 'file.jpg');
    try {
      const response = await axios.request({method: 'POST', url, data});
      console.log('FIELDS:', response.data.fields);
      console.log('FILE:', response.data.files && response.data.files.file1);
    } catch (error) {
      console.error('ERROR:', error.message);
    }
    server.close();
  });
})();

